#!/bin/bash
# Generated by taskmine. Harbor copies this directory to /tests and runs this script after the
# agent finishes; the reward file is the only thing it reads (the exit code is ignored).
#
#   test.sh                      Harbor's own verifier, in the agent's container: restore the test
#                                side, run the tests, write /logs/verifier/reward.txt. The reward
#                                starts at 0, so if python3 or the grader is missing the task fails.
#   test.sh --stage untrusted    PR #120's staged grader, as the agent user: run the tests on a copy
#                                of the repository and write the JUnit report and run.json to $OUT.
#                                No reward: what this stage writes is evidence, never a score.
#   test.sh --stage trusted      PR #120's staged grader, as the grader user, after the agent's
#                                processes are gone: read $IN's JUnit report and this directory's
#                                expected.json, write $OUT/reward.json. It runs a root-owned python3
#                                in isolated mode, from here, and reads nothing from the repository.
# IN and OUT default to /logs/verifier, as in PR #120.
set -u
MODE=all
[ "${1:-}" = --stage ] && MODE=${2:-}
case "$MODE" in all|untrusted|trusted) ;; *) echo "usage: test.sh [--stage untrusted|trusted]" >&2; exit 2 ;; esac
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
APP="${TASKMINE_APP:-/app}"

if [ "$MODE" = all ]; then
  LOGS="${TASKMINE_LOGS:-/logs/verifier}"
  mkdir -p "$LOGS"
  echo 0 > "$LOGS/reward.txt"
  python3 "$HERE/grader.py" --tests "$HERE" --app "$APP" --logs "$LOGS"
  exit 0
fi

L="${OUT:-/logs/verifier}"
mkdir -p "$L"
if [ "$MODE" = untrusted ]; then
  python3 "$HERE/grader.py" --stage untrusted --tests "$HERE" --app "$APP" --out "$L"
  exit 0
fi

# trusted: no program from the agent's reach. PATH is reset, and python3 must be a root-owned file
# that no one else can write, outside every directory the agent could write to.
export PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin
PY=
for c in /usr/bin/python3 /usr/local/bin/python3; do
  r=$(readlink -f "$c" 2>/dev/null) || continue
  case "$r" in /app/*|/work/*|/home/*|/tmp/*|/var/tmp/*|/run/*|/logs/*|/installed-agent/*|"$APP"/*) continue ;; esac
  [ -f "$r" ] && [ -x "$r" ] || continue
  set -- $(ls -ldn "$r")  # mode, links, uid, ...: owned by uid 0, not writable by group or others
  [ "$3" = 0 ] && [ "${1:5:1}" != w ] && [ "${1:8:1}" != w ] || continue
  PY=$r
  break
done
if [ -z "$PY" ]; then
  echo "taskmine grader: no root-owned python3 outside the agent's reach for the trusted stage; not grading" >&2
  exit 3
fi
cd "$HERE" || exit 3
exec "$PY" -I -S "$HERE/grader.py" --stage trusted --tests "$HERE" --in "${IN:-/logs/verifier}" --out "$L"
